    dot_uv = ux*vx + uy*vy
    cos_apq = dot_uv / (ulen * vlen)
    # Clamp due to numerical rounding
    if cos_apq > 1: cos_apq = 1
    if cos_apq < -1: cos_apq = -1
    ang_apq = math.acos(cos_apq)
    if ang_apq <= 0:
        return (False, None)

    cos_c = 0.5/s
    if cos_c > 1 or cos_c < -1:
        return (False, None)
    ang_c = math.acos(cos_c)
    if ang_c <= 0:
        return (False, None)

    r = ang_c / ang_apq
    if r <= 0:
        return (False, None)

    # Difficulty enforcement: avoid trivial cases
    # 1) r not too close to a simple rational with small denominator
    def near_small_rational(x, max_q=18, tol=8e-5):
        for q in range(1, max_q+1):
            p = round(x*q)
            if abs(x - p/q) < tol:
                return True
        return False
    if near_small_rational(r):
        return (False, None)

    # 2) avoid rounding ambiguity when flooring
    rr = scale * r
    frac = rr - math.floor(rr)
    if frac < 1e-8 or (1 - frac) < 1e-8:
        return (False, None)

    answer = math.floor(rr)
    return (True, answer)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

